CSS='''*{box-sizing:border-box}body{margin:0;background:#10171c;color:#edf0e9;font:16px/1.55 system-ui}main{max-width:1300px;margin:auto;padding:32px 24px}a{color:#22d3ee}h1{font-size:clamp(36px,5vw,62px);font-weight:550;letter-spacing:-2px;line-height:1.1;margin:16px 0}h2{font-size:24px;font-weight:550}.kicker{color:#22d3ee;font-size:12px;letter-spacing:2px}p{color:#a3b0b7}video{width:100%;display:block;background:#000;border-radius:8px}button,select{font:inherit;color:#edf0e9;background:#1c2a33;border:1px solid #485e69;border-radius:6px;padding:10px 14px;cursor:pointer}button:hover,button.active{border-color:#22d3ee}nav,.controls{display:flex;flex-wrap:wrap;gap:10px;margin:20px 0}.layout{display:grid;grid-template-columns:minmax(0,3fr) minmax(260px,1fr);gap:24px}.points{background:#18232a;border:1px solid #35434a;border-radius:8px;padding:20px}.points p{margin:14px 0;color:#d2dce0}.point{padding:14px 0;border-bottom:1px solid #35434a}.point:last-child{border:0}.pill{color:#22d3ee;font-size:13px}.limit{font-size:13px;color:#8fa2ad;margin-top:20px}.pair{display:grid;grid-template-columns:1fr 1fr;gap:20px}.player{min-width:0}.player select{width:100%;margin-bottom:14px}.player .points{margin-top:14px}footer{margin-top:35px;border-top:1px solid #35434a;padding-top:20px;color:#8fa2ad;font-size:13px}@media(max-width:850px){.layout,.pair{grid-template-columns:1fr}main{padding:24px 16px}}'''
CASES=[{'id':'E','title':'Pereira vs Adesanya · clear standing exchange','src':'color_videos/E-colored-figures.mp4','points':['Our strongest new colored-body example: two separated standing fighters.','Watch the hands, face and feet track with the movement; the figure is a candidate, not verified anatomy.','Clothing and motion support color association for 435 of 482 detector candidates. That is coverage, not identity accuracy.']},{'id':'A','title':'Standing exchange · original tracked sample','src':'color_videos/A-colored-figures.mp4','points':['Watch the whole-body rhythm through a standing exchange.','Cyan and coral follow clothing roles. Gray marks unresolved ownership.','Visible proximity does not establish a clean hit or physical impact force.']},{'id':'B','title':'Wrestling entry · where tracking gets harder','src':'color_videos/B-colored-figures.mp4','points':['Watch the bodies overlap during the entry.','Color assignment deliberately drops when ownership is ambiguous.','This same episode was missed by the tested past-only takedown forecasts.']},{'id':'F','title':'Fence clinch · inspect the limits','src':'color_videos/F-colored-figures.mp4','points':['Close contact makes hand and limb ownership substantially harder.','Merged or ambiguous bodies stay gray rather than being forced into two fighters.','Whole-body anatomy in clinches is not reliable yet.']}]
html='''<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>MMA · Tracked videos</title><style>__CSS__</style></head><body><main><div class="kicker">MMA / WATCH THE MOVEMENT</div><h1>The video. The tracking.<br>The key points.</h1><p>Pick an exchange and press play. Cyan and coral identify clothing roles; uncertain bodies stay gray.</p><nav id="choices"></nav><div class="layout"><section><video id="video" controls muted playsinline preload="metadata"></video><div class="controls"><button id="play">Play / pause</button><button id="restart">Replay</button><select id="speed" aria-label="Playback speed"><option value="1">1× speed</option><option value=".5">0.5× speed</option><option value=".25">0.25× speed</option></select></div></section><aside class="points"><span class="pill">WHAT TO NOTICE</span><h2 id="title"></h2><div id="points"></div></aside></div><p class="limit">133-point estimates at 12 Hz. Face, hand and foot detail can be wrong under blur or occlusion. Contact, clean hits and damage are not inferred from skeleton proximity.</p><footer><a href="mcgregor/index.html">McGregor across eras — tracked videos + insights ↗</a> · <a href="assessment/report.txt">Research findings</a></footer></main><script>const DATA=__DATA__,$=id=>document.getElementById(id);const v=$('video');function choose(i){v.pause();v.src=DATA[i].src;$('title').textContent=DATA[i].title;$('points').innerHTML=DATA[i].points.map(p=>'<p class="point">'+p+'</p>').join('');document.querySelectorAll('[data-choice]').forEach(b=>b.classList.toggle('active',+b.dataset.choice===i));v.load();v.playbackRate=+$('speed').value}$('choices').innerHTML=DATA.map((d,i)=>'<button data-choice="'+i+'">'+d.id+' · '+d.title.split(' · ')[0]+'</button>').join('');document.querySelectorAll('[data-choice]').forEach(b=>b.onclick=()=>choose(+b.dataset.choice));$('play').onclick=()=>v.paused?v.play():v.pause();$('restart').onclick=()=>{v.currentTime=0;v.play()};$('speed').onchange=()=>v.playbackRate=+$('speed').value;choose(0);</script></body></html>'''.replace('__CSS__',CSS).replace('__DATA__',json.dumps(CASES))
